#if SCR_FRAMETIME
namespace CompetitiveRounds
{
    /// <summary>FrameTime M3 census ids (METHOD-V4.md 3.12; VR5), generated by
    /// tools/frametime/gen_entries.py from tools/frametime/gate_specs/entries.py, which says
    /// which entries are listed and why: the outermost live entries of INVENTORY.md, each with
    /// its component and shape (a patched entry is its own shape). RegisterAll runs once at clock
    /// install, so every census line lists every gated entry, reached or not; it logs the count,
    /// any id left unregistered and any registered twice. PatchType names each patched entry's
    /// patch class (the class holding its census gate), which FtCalib calibrates.</summary>
    internal static class FtE
    {
        internal const int HE_p1 = 0;
        internal const int HE_p2 = 1;
        internal const int HE_p3 = 2;
        internal const int HE_p4 = 3;
        internal const int HE_p5 = 4;
        internal const int HE_p6 = 5;
        internal const int HE_p7 = 6;
        internal const int HE_p8 = 7;
        internal const int HE_p9 = 8;
        internal const int CE_c7 = 9;
        internal const int CE_p1 = 10;
        internal const int CE_p2 = 11;
        internal const int CE_p3 = 12;
        internal const int CE_p4 = 13;
        internal const int CE_p5 = 14;
        internal const int CE_p6 = 15;
        internal const int CE_p7 = 16;
        internal const int CE_p8 = 17;
        internal const int CE_p9 = 18;
        internal const int CE_p10 = 19;
        internal const int CE_p11 = 20;
        internal const int CE_p12 = 21;
        internal const int CE_p13 = 22;
        internal const int CE_p14 = 23;
        internal const int CE_p15 = 24;
        internal const int CE_p16 = 25;
        internal const int CE_p17 = 26;
        internal const int CE_p18 = 27;
        internal const int CE_p19 = 28;
        internal const int SE_c50 = 29;
        internal const int SE_c52 = 30;
        internal const int SE_c53 = 31;
        internal const int SE_p1 = 32;
        internal const int SE_p2 = 33;
        internal const int SE_p3 = 34;
        internal const int PT_c5 = 35;
        internal const int PT_p1 = 36;
        internal const int IC_c6 = 37;
        internal const int IC_p1 = 38;
        internal const int IC_p4 = 39;
        internal const int CD_c6 = 40;
        internal const int CD_c7 = 41;
        internal const int PB_c2 = 42;
        internal const int PB_c3 = 43;

        internal const int Count = 44;

        private static bool _done;

        internal static void RegisterAll()
        {
            if (_done) return;
            _done = true;
            FtCensus.Set(HE_p1, "HE-p1:PhotonNetwork.ExecuteRpc", FtSpan.Hit, "HE_p1");
            FtCensus.Set(HE_p2, "HE-p2:HealthHandler.RPCA_SendTakeDamage", FtSpan.Hit, "HE_p2");
            FtCensus.Set(HE_p3, "HE-p3:HealthHandler.RPCA_SendTakeForce", FtSpan.Hit, "HE_p3");
            FtCensus.Set(HE_p4, "HE-p4:HealthHandler.DoDamage", FtSpan.Hit, "HE_p4");
            FtCensus.Set(HE_p5, "HE-p5:Block.RPCA_DoBlock", FtSpan.Hit, "HE_p5");
            FtCensus.Set(HE_p6, "HE-p6:ProjectileInit.RPCA_Init", FtSpan.Hit, "HE_p6");
            FtCensus.Set(HE_p7, "HE-p7:ProjectileInit.RPCA_Init_noAmmoUse", FtSpan.Hit, "HE_p7");
            FtCensus.Set(HE_p8, "HE-p8:ProjectileInit.RPCA_Init_SeparateGun", FtSpan.Hit, "HE_p8");
            FtCensus.Set(HE_p9, "HE-p9:ProjectileHit.RPCA_DoHit", FtSpan.Hit, "HE_p9");
            FtCensus.Set(CE_c7, "CE-c7:CombatEvidence.Tick", FtSpan.Combat, "call");
            FtCensus.Set(CE_p1, "CE-p1:Gun.Attack", FtSpan.Combat, "CE_p1");
            FtCensus.Set(CE_p2, "CE-p2:ProjectileInit.RPCA_Init", FtSpan.Combat, "CE_p2");
            FtCensus.Set(CE_p3, "CE-p3:ProjectileInit.RPCA_Init_noAmmoUse", FtSpan.Combat, "CE_p3");
            FtCensus.Set(CE_p4, "CE-p4:ProjectileInit.RPCA_Init_SeparateGun", FtSpan.Combat, "CE_p4");
            FtCensus.Set(CE_p5, "CE-p5:GunAmmo.ReloadAmmo", FtSpan.Combat, "CE_p5");
            FtCensus.Set(CE_p6, "CE-p6:ProjectileHit.RPCA_DoHit", FtSpan.Combat, "CE_p6");
            FtCensus.Set(CE_p7, "CE-p7:ProjectileHit.Hit", FtSpan.Combat, "CE_p7");
            FtCensus.Set(CE_p8, "CE-p8:Block.RPCA_DoBlock", FtSpan.Combat, "CE_p8");
            FtCensus.Set(CE_p9, "CE-p9:Block.TryBlock", FtSpan.Combat, "CE_p9");
            FtCensus.Set(CE_p10, "CE-p10:CharacterStatModifiers.DealtDamage", FtSpan.Combat, "CE_p10");
            FtCensus.Set(CE_p11, "CE-p11:BounceEffectRetarget.SetNewVel", FtSpan.Combat, "CE_p11");
            FtCensus.Set(CE_p12, "CE-p12:ScreenEdgeBounce.DoHit", FtSpan.Combat, "CE_p12");
            FtCensus.Set(CE_p13, "CE-p13:SyncProjectile.OnPhotonSerializeView", FtSpan.Combat, "CE_p13");
            FtCensus.Set(CE_p14, "CE-p14:HealthHandler.RPCA_SendTakeForce", FtSpan.Combat, "CE_p14");
            FtCensus.Set(CE_p15, "CE-p15:HealthHandler.RPCA_SendTakeDamage", FtSpan.Combat, "CE_p15");
            FtCensus.Set(CE_p16, "CE-p16:HealthHandler.RPCA_Die", FtSpan.Combat, "CE_p16");
            FtCensus.Set(CE_p17, "CE-p17:HealthHandler.RPCA_Die_Phoenix", FtSpan.Combat, "CE_p17");
            FtCensus.Set(CE_p18, "CE-p18:BounceEffectRetarget.FindTarget", FtSpan.Combat, "CE_p18");
            FtCensus.Set(CE_p19, "CE-p19:MoveTransform.Update", FtSpan.Combat, "CE_p19");
            FtCensus.Set(SE_c50, "SE-c50:SeatEvidence.NoteView", FtSpan.Seat, "call");
            FtCensus.Set(SE_c52, "SE-c52:SeatEvidence.CompatTick", FtSpan.Seat, "call");
            FtCensus.Set(SE_c53, "SE-c53:SeatEvidence.Tick", FtSpan.Seat, "call");
            FtCensus.Set(SE_p1, "SE-p1:PhotonNetwork.RPC", FtSpan.Seat, "SE_p1");
            FtCensus.Set(SE_p2, "SE-p2:Block.DoBlock", FtSpan.Seat, "SE_p2");
            FtCensus.Set(SE_p3, "SE-p3:Block.TryBlockMe", FtSpan.Seat, "SE_p3");
            FtCensus.Set(PT_c5, "PT-c5:PointEvidence.Drain", FtSpan.Point, "call");
            FtCensus.Set(PT_p1, "PT-p1:Saw.Update", FtSpan.Point, "PT_p1");
            FtCensus.Set(IC_c6, "IC-c6:IdentityClockEvidence.Tick", FtSpan.Identity, "call");
            FtCensus.Set(IC_p1, "IC-p1:PhotonNetwork.ExecuteRpc", FtSpan.Identity, "IC_p1");
            FtCensus.Set(IC_p4, "IC-p4:SyncPlayerMovement.OnPhotonSerializeView", FtSpan.Identity, "IC_p4");
            FtCensus.Set(CD_c6, "CD-c6:CardDrawEvidence.Tick", FtSpan.CardDraw, "call");
            FtCensus.Set(CD_c7, "CD-c7:CardDrawEvidence.EnsureCensusDump", FtSpan.CardDraw, "call");
            FtCensus.Set(PB_c2, "PB-c2:PeerBuild.StageBuildProp", FtSpan.PeerBuild, "call");
            FtCensus.Set(PB_c3, "PB-c3:PeerBuild.Tick", FtSpan.PeerBuild, "call");
            int missing = 0;
            for (int i = 0; i < Count; i++) if (FtCensus.Names[i] == null) missing++;
            Plugin.Log.LogInfo("[FRAME-TIME] census registered=" + FtCensus.Count + " expected=" + Count + " missing=" + missing
                + " duplicates=" + FtCensus.Duplicates);
        }

        /// <summary>A patched entry's patch class; null for a direct-call entry.</summary>
        internal static System.Type PatchType(int id)
        {
            switch (id)
            {
                case HE_p1: return typeof(HitEvidence_ExecuteRpcPatch);
                case HE_p2: return typeof(HitEvidence_DamagePatch);
                case HE_p3: return typeof(HitEvidence_ForcePatch);
                case HE_p4: return typeof(HitEvidence_DotPatch);
                case HE_p5: return typeof(HitEvidence_BlockPatch);
                case HE_p6: return typeof(HitEvidence_SpawnAmmoPatch);
                case HE_p7: return typeof(HitEvidence_SpawnNoAmmoPatch);
                case HE_p8: return typeof(HitEvidence_SpawnSeparatePatch);
                case HE_p9: return typeof(HitEvidence_ImpactPatch);
                case CE_p1: return typeof(CombatEvidence_AttackPatch);
                case CE_p2: return typeof(CombatEvidence_InitAmmoPatch);
                case CE_p3: return typeof(CombatEvidence_InitNoAmmoPatch);
                case CE_p4: return typeof(CombatEvidence_InitSeparatePatch);
                case CE_p5: return typeof(CombatEvidence_ReloadPatch);
                case CE_p6: return typeof(CombatEvidence_HitPatch);
                case CE_p7: return typeof(CombatEvidence_ContactPatch);
                case CE_p8: return typeof(CombatEvidence_BlockPatch);
                case CE_p9: return typeof(CombatEvidence_TryBlockPatch);
                case CE_p10: return typeof(CombatEvidence_DealtPatch);
                case CE_p11: return typeof(CombatEvidence_TargetBouncePatch);
                case CE_p12: return typeof(CombatEvidence_EdgeBouncePatch);
                case CE_p13: return typeof(CombatEvidence_SyncPatch);
                case CE_p14: return typeof(CombatEvidence_ForcePatch);
                case CE_p15: return typeof(CombatEvidence_DamagePatch);
                case CE_p16: return typeof(CombatEvidence_DiePatch);
                case CE_p17: return typeof(CombatEvidence_DiePhoenixPatch);
                case CE_p18: return typeof(CombatEvidence_FindTargetPatch);
                case CE_p19: return typeof(CombatEvidence_MovePatch);
                case SE_p1: return typeof(SeatEvidence_RpcSendPatch);
                case SE_p2: return typeof(SeatEvidence_DoBlockPatch);
                case SE_p3: return typeof(SeatEvidence_TryBlockMePatch);
                case PT_p1: return typeof(SawPointEvidencePatch);
                case IC_p1: return typeof(IdentityClock_ExecuteRpcPatch);
                case IC_p4: return typeof(IdentityClock_MovementPatch);
                default: return null;
            }
        }
    }
}
#endif
